# Encode key patterns for component analysis
from collections import deque

def comps(points, diag=True):
    pts=set(points); out=[]
    while pts:
        start=pts.pop(); q=[start]; comp={start}
        while q:
            r,c=q.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr==dc==0: continue
                    if not diag and abs(dr)+abs(dc)!=1: continue
                    p=(r+dr,c+dc)
                    if p in pts:
                        pts.remove(p); comp.add(p); q.append(p)
        out.append(comp)
    return sorted(out,key=lambda x:(-len(x), min(x)))

def norm(shape):
    rs=[r for r,c in shape]; cs=[c for r,c in shape]
    return frozenset((r-min(rs),c-min(cs)) for r,c in shape)

def transform(shape, kind):
    # normalize after D4 transform
    vals=[]
    for r,c in shape:
        if kind==0: p=(r,c)
        elif kind==1: p=(c,-r) # clockwise in image coords? 
        elif kind==2: p=(-r,-c)
        elif kind==3: p=(-c,r)
        elif kind==4: p=(r,-c)
        elif kind==5: p=(-r,c)
        elif kind==6: p=(c,r)
        elif kind==7: p=(-c,-r)
        vals.append(p)
    return norm(vals)

# demo 1 panels points (local row, col)
d1=[{(0,7),(1,8),(2,7),(6,1),(6,8)},
    {(1,5),(1,8),(3,4),(4,5),(5,4),(6,1),(6,8)},
    {(1,1),(1,3),(1,5),(1,8),(2,2),(4,2),(4,5),(6,1),(6,8)}]
# d2 panels
d2=[{(0,3),(1,3),(1,4),(1,6),(2,3)},
    {(0,1),(0,4),(0,6),(1,0),(1,1),(1,2)},
    {(0,1),(0,4),(0,6),(2,2),(3,1),(3,2),(4,2)},
    {(0,1),(0,4),(0,6),(2,6),(3,5),(3,6),(4,6)}]
# d3 panels
d3=[{(5,4),(5,6),(6,0),(6,5),(6,7),(6,9),(7,5),(9,5),(9,9)},
    {(1,2),(1,5),(4,5),(5,2),(6,0),(6,7),(6,9),(7,5),(8,2),(9,2),(9,5),(9,9),(10,1),(10,3)}]
for di, panels in [(1,d1),(2,d2),(3,d3)]:
    print('demo',di)
    for i,p in enumerate(panels):
        print('panel',i+1,'8conn sizes',list(map(len,comps(p,True))),'4conn',list(map(len,comps(p,False))))
        print([(len(c), sorted(c), norm(c)) for c in comps(p,True) if len(c)>=3])

def life_step(points, rows, cols):
    counts={}
    for r,c in points:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==dc==0: continue
                p=(r+dr,c+dc)
                if 0<=p[0]<rows and 0<=p[1]<cols:
                    counts[p]=counts.get(p,0)+1
    return {p for p,n in counts.items() if n==3 or (n==2 and p in points)}
for name,p,shape,output in [
 ('d1C',d1[2],(8,10),{(5,2),(6,1),(7,2)}),
 ('d2D',d2[3],(6,8),{(0,5),(1,5),(1,6),(2,5)}),
 ('d3P2',d3[1],(12,12),{(5,2),(6,0),(6,1),(7,2)})]:
    nxt=life_step(p,*shape)
    print(name, 'life count',len(nxt),'equals output',nxt==output, 'nxt',sorted(nxt)[:30])

